1	// Public acceptance battery for `clipper2::engine`.
2	// Build:  rustc --edition 2021 -A dead_code harness.rs -o harness && ./harness
3	// Every implementation must print "RESULT ok" with 0 failures.
4	
5	mod clipper2;
6	use clipper2::*;
7	
8	struct T {
9	    pass: u32,
10	    fail: u32,
11	}
12	
13	impl T {
14	    fn new() -> T {
15	        T { pass: 0, fail: 0 }
16	    }
17	    fn check(&mut self, name: &str, cond: bool, detail: &str) {
18	        if cond {
19	            self.pass += 1;
20	            println!("PASS  {}", name);
21	        } else {
22	            self.fail += 1;
23	            println!("FAIL  {}  <<{}>>", name, detail);
24	        }
25	    }
26	    fn eqi(&mut self, name: &str, got: i64, want: i64) {
27	        self.check(name, got == want, &format!("got {} want {}", got, want));
28	    }
29	    fn eqf(&mut self, name: &str, got: f64, want: f64, tol: f64) {
30	        self.check(
31	            name,
32	            (got - want).abs() <= tol,
33	            &format!("got {} want {} tol {}", got, want, tol),
34	        );
35	    }
36	}
37	
38	fn rect(l: i64, t: i64, r: i64, b: i64) -> Path64 {
39	    // positive (area > 0) orientation
40	    vec![
41	        Point64::new(l, t),
42	        Point64::new(r, t),
43	        Point64::new(r, b),
44	        Point64::new(l, b),
45	    ]
46	}
47	
48	fn rrect(l: i64, t: i64, r: i64, b: i64) -> Path64 {
49	    reverse_path(&rect(l, t, r, b))
50	}
51	
52	fn total_area(paths: &Paths64) -> f64 {
53	    areas(paths)
54	}
55	
56	fn abs_area_sum(paths: &Paths64) -> f64 {
57	    paths.iter().map(|p| area(p).abs()).sum()
58	}
59	
60	/// Structural validation shared by every case.
61	fn validate(t: &mut T, name: &str, sol: &Paths64, preserve_collinear: bool) {
62	    for (i, p) in sol.iter().enumerate() {
63	        t.check(
64	            &format!("{}/len[{}]", name, i),
65	            p.len() >= 3,
66	            &format!("contour has {} vertices", p.len()),
67	        );
68	        if p.len() < 3 {
69	            continue;
70	        }
71	        let n = p.len();
72	        let mut dup = false;
73	        for j in 0..n {
74	            if p[j] == p[(j + 1) % n] {
75	                dup = true;
76	            }
77	        }
78	        t.check(&format!("{}/nodup[{}]", name, i), !dup, "duplicate vertex");
79	        t.check(
80	            &format!("{}/nonzero[{}]", name, i),
81	            area(p) != 0.0,
82	            "zero area contour",
83	        );
84	        if !preserve_collinear {
85	            let mut col = false;
86	            for j in 0..n {
87	                let a = p[j];
88	                let b = p[(j + 1) % n];
89	                let c = p[(j + 2) % n];
90	                if cross_product_exact(a, b, c) == 0 {
91	                    col = true;
92	                }
93	            }
94	            t.check(
95	                &format!("{}/nocollinear[{}]", name, i),
96	                !col,
97	                "collinear vertex retained",
98	            );
99	        }
100	    }
101	    // no two output edges may properly cross
102	    let mut crossings = 0;
103	    let flat: Vec<(Point64, Point64)> = sol
104	        .iter()
105	        .flat_map(|p| {
106	            let n = p.len();
107	            (0..n).map(move |i| (p[i], p[(i + 1) % n]))
108	        })
109	        .collect();
110	    for i in 0..flat.len() {
111	        for j in (i + 1)..flat.len() {
112	            let (a1, a2) = flat[i];
113	            let (b1, b2) = flat[j];
114	            let d1 = cross_product_exact(a1, a2, b1).signum();
115	            let d2 = cross_product_exact(a1, a2, b2).signum();
116	            let d3 = cross_product_exact(b1, b2, a1).signum();
117	            let d4 = cross_product_exact(b1, b2, a2).signum();
118	            if d1 != 0 && d2 != 0 && d3 != 0 && d4 != 0 && d1 != d2 && d3 != d4 {
119	                crossings += 1;
120	            }
121	        }
122	    }
123	    t.eqi(&format!("{}/nocross", name), crossings, 0);
124	}
125	
126	fn main() {
127	    let mut t = T::new();
128	
129	    // 1 -- identity union of a single square
130	    {
131	        let s: Paths64 = vec![rect(0, 0, 100, 100)];
132	        let sol = union_paths(&s, FillRule::Positive);
133	        t.eqi("01.count", sol.len() as i64, 1);
134	        t.eqf("01.area", total_area(&sol), 10000.0, 0.5);
135	        t.check("01.positive", total_area(&sol) > 0.0, "outer must be positive");
136	        validate(&mut t, "01", &sol, false);
137	    }
138	
139	    // 2 -- two overlapping squares merge
140	    {
141	        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(50, 50, 150, 150)];
142	        let sol = union_paths(&s, FillRule::Positive);
143	        t.eqi("02.count", sol.len() as i64, 1);
144	        t.eqf("02.area", total_area(&sol), 17500.0, 0.5);
145	        validate(&mut t, "02", &sol, false);
146	    }
147	
148	    // 3 -- two disjoint squares stay separate
149	    {
150	        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(200, 200, 300, 300)];
151	        let sol = union_paths(&s, FillRule::Positive);
152	        t.eqi("03.count", sol.len() as i64, 2);
153	        t.eqf("03.area", total_area(&sol), 20000.0, 0.5);
154	        validate(&mut t, "03", &sol, false);
155	    }
156	
157	    // 4 -- square with a hole (reversed inner contour)
158	    {
159	        let s: Paths64 = vec![rect(0, 0, 100, 100), rrect(25, 25, 75, 75)];
160	        let sol = union_paths(&s, FillRule::Positive);
161	        t.eqi("04.count", sol.len() as i64, 2);
162	        t.eqf("04.net_area", total_area(&sol), 7500.0, 0.5);
163	        t.eqf("04.abs_area", abs_area_sum(&sol), 12500.0, 0.5);
164	        let neg = sol.iter().filter(|p| area(p) < 0.0).count();
165	        t.eqi("04.one_hole", neg as i64, 1);
166	        validate(&mut t, "04", &sol, false);
167	    }
168	
169	    // 5 -- self-intersecting bowtie, every fill rule
170	    {
171	        let bow: Path64 = vec![
172	            Point64::new(0, 0),
173	            Point64::new(100, 0),
174	            Point64::new(0, 100),
175	            Point64::new(100, 100),
176	        ];
177	        let s: Paths64 = vec![bow];
178	
179	        let sol = union_paths(&s, FillRule::Positive);
180	        t.eqi("05p.count", sol.len() as i64, 1);
181	        t.eqf("05p.area", total_area(&sol), 2500.0, 1.0);
182	        validate(&mut t, "05p", &sol, false);
183	
184	        let sol = union_paths(&s, FillRule::Negative);
185	        t.eqi("05n.count", sol.len() as i64, 1);
186	        t.eqf("05n.abs_area", abs_area_sum(&sol), 2500.0, 1.0);
187	        validate(&mut t, "05n", &sol, false);
188	
189	        let sol = union_paths(&s, FillRule::NonZero);
190	        t.eqi("05nz.count", sol.len() as i64, 2);
191	        t.eqf("05nz.abs_area", abs_area_sum(&sol), 5000.0, 1.0);
192	        validate(&mut t, "05nz", &sol, false);
193	
194	        let sol = union_paths(&s, FillRule::EvenOdd);
195	        t.eqi("05eo.count", sol.len() as i64, 2);
196	        t.eqf("05eo.abs_area", abs_area_sum(&sol), 5000.0, 1.0);
197	        validate(&mut t, "05eo", &sol, false);
198	    }
199	
200	    // 6 -- the same square twice: winding 2
201	    {
202	        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(0, 0, 100, 100)];
203	        let sol = union_paths(&s, FillRule::Positive);
204	        t.eqi("06p.count", sol.len() as i64, 1);
205	        t.eqf("06p.area", total_area(&sol), 10000.0, 0.5);
206	        let sol = union_paths(&s, FillRule::EvenOdd);
207	        t.eqi("06eo.count", sol.len() as i64, 0);
208	    }
209	
210	    // 7/8/9 -- intersection, difference, xor
211	    {
212	        let a: Paths64 = vec![rect(0, 0, 100, 100)];
213	        let b: Paths64 = vec![rect(50, 50, 150, 150)];
214	
215	        let sol = intersect(&a, &b, FillRule::Positive);
216	        t.eqi("07.count", sol.len() as i64, 1);
217	        t.eqf("07.area", total_area(&sol), 2500.0, 0.5);
218	        validate(&mut t, "07", &sol, false);
219	
220	        let sol = difference(&a, &b, FillRule::Positive);
221	        t.eqi("08.count", sol.len() as i64, 1);
222	        t.eqf("08.area", total_area(&sol), 7500.0, 0.5);
223	        validate(&mut t, "08", &sol, false);
224	
225	        let c: Paths64 = vec![rect(50, 25, 150, 75)];
226	        let sol = xor_paths(&a, &c, FillRule::Positive);
227	        t.eqi("09.count", sol.len() as i64, 2);
228	        t.eqf("09.abs_area", abs_area_sum(&sol), 10000.0, 0.5);
229	        validate(&mut t, "09", &sol, false);
230	    }
231	
232	    // 10 -- collinear vertices are dropped by default, kept on request
233	    {
234	        let s: Paths64 = vec![vec![
235	            Point64::new(0, 0),
236	            Point64::new(50, 0),
237	            Point64::new(100, 0),
238	            Point64::new(100, 100),
239	            Point64::new(0, 100),
240	        ]];
241	        let sol = union_paths(&s, FillRule::Positive);
242	        t.eqi("10.count", sol.len() as i64, 1);
243	        t.eqi("10.vertices", sol[0].len() as i64, 4);
244	        t.eqf("10.area", total_area(&sol), 10000.0, 0.5);
245	        validate(&mut t, "10", &sol, false);
246	
247	        let sol = boolean_op(
248	            ClipType::Union,
249	            FillRule::Positive,
250	            &s,
251	            &Vec::new(),
252	            true,
253	            false,
254	        );
255	        t.eqi("10pc.count", sol.len() as i64, 1);
256	        t.eqi("10pc.vertices", sol[0].len() as i64, 5);
257	    }
258	
259	    // 11 -- nested same-orientation squares collapse to the outer one
260	    {
261	        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(25, 25, 75, 75)];
262	        let sol = union_paths(&s, FillRule::Positive);
263	        t.eqi("11.count", sol.len() as i64, 1);
264	        t.eqf("11.area", total_area(&sol), 10000.0, 0.5);
265	        validate(&mut t, "11", &sol, false);
266	    }
267	
268	    // 12/13 -- empty and degenerate input
269	    {
270	        let sol = union_paths(&Vec::new(), FillRule::Positive);
271	        t.eqi("12.count", sol.len() as i64, 0);
272	
273	        let s: Paths64 = vec![
274	            vec![Point64::new(0, 0), Point64::new(10, 10)],
275	            vec![Point64::new(0, 0)],
276	            Vec::new(),
277	            vec![
278	                Point64::new(0, 0),
279	                Point64::new(10, 0),
280	                Point64::new(20, 0),
281	            ],
282	        ];
283	        let sol = union_paths(&s, FillRule::Positive);
284	        t.eqi("13.count", sol.len() as i64, 0);
285	    }
286	
287	    // 14 -- large coordinates must not overflow
288	    {
289	        let g = 1_000_000_000i64;
290	        let s: Paths64 = vec![rect(0, 0, g, g), rect(g / 2, g / 2, g + g / 2, g + g / 2)];
291	        let sol = union_paths(&s, FillRule::Positive);
292	        t.eqi("14.count", sol.len() as i64, 1);
293	        let expect = 2.0 * (g as f64) * (g as f64) - 0.25 * (g as f64) * (g as f64);
294	        t.eqf("14.area", total_area(&sol), expect, expect * 1e-9);
295	        validate(&mut t, "14", &sol, false);
296	    }
297	
298	    // 15 -- reverse_solution flips every orientation
299	    {
300	        let s: Paths64 = vec![rect(0, 0, 100, 100), rrect(25, 25, 75, 75)];
301	        let sol = boolean_op(
302	            ClipType::Union,
303	            FillRule::Positive,
304	            &s,
305	            &Vec::new(),
306	            false,
307	            true,
308	        );
309	        t.eqi("15.count", sol.len() as i64, 2);
310	        t.eqf("15.net_area", total_area(&sol), -7500.0, 0.5);
311	        let pos = sol.iter().filter(|p| area(p) > 0.0).count();
312	        t.eqi("15.one_pos", pos as i64, 1);
313	    }
314	
315	    // 16 -- union is idempotent
316	    {
317	        let s: Paths64 = vec![rect(0, 0, 100, 100), rect(50, 50, 150, 150)];
318	        let once = union_paths(&s, FillRule::Positive);
319	        let twice = union_paths(&once, FillRule::Positive);
320	        t.eqi("16.count", twice.len() as i64, once.len() as i64);
321	        t.eqf("16.area", total_area(&twice), total_area(&once), 0.5);
322	    }
323	
324	    // 17 -- edge-to-edge abutting squares merge into one rectangle
325	    {
326	        let s: Paths64 = vec![rect(0, 0, 50, 100), rect(50, 0, 100, 100)];
327	        let sol = union_paths(&s, FillRule::Positive);
328	        t.eqi("17.count", sol.len() as i64, 1);
329	        t.eqi("17.vertices", sol[0].len() as i64, 4);
330	        t.eqf("17.area", total_area(&sol), 10000.0, 0.5);
331	        validate(&mut t, "17", &sol, false);
332	    }
333	
334	    // 18 -- a ring unioned with a plug that fills its hole
335	    {
336	        let s: Paths64 = vec![rect(0, 0, 100, 100), rrect(25, 25, 75, 75)];
337	        let plug: Paths64 = vec![rect(25, 25, 75, 75)];
338	        let sol = union_two(&s, &plug, FillRule::Positive);
339	        t.eqi("18.count", sol.len() as i64, 1);
340	        t.eqf("18.area", total_area(&sol), 10000.0, 0.5);
341	        validate(&mut t, "18", &sol, false);
342	    }
343	
344	    println!("---");
345	    println!("PASSED {} FAILED {}", t.pass, t.fail);
346	    println!("RESULT {}", if t.fail == 0 { "ok" } else { "bad" });
347	}
