1	//! Core geometric types, constants and predicates.
2	//!
3	//! This is a from-scratch, `std`-only reimplementation of the pieces of the
4	//! Clipper2 public interface that the entry program depends on.  Nothing in
5	//! here allocates beyond `Vec`, and no third party crate is used.
6	
7	use std::ops::{Add, Mul, Neg, Sub};
8	
9	// ---------------------------------------------------------------------------
10	// Constants
11	// ---------------------------------------------------------------------------
12	
13	/// Value reported by the original library's `CLIPPER2_VERSION`.
14	pub const CLIPPER2_VERSION: &str = "1.4.0";
15	
16	pub const PI: f64 = 3.141592653589793238;
17	
18	/// Arc tolerance used when the caller leaves `arc_tolerance` at 0.
19	pub const DEFAULT_ARC_TOLERANCE: f64 = 0.25;
20	
21	/// Anything below this magnitude is treated as zero by the offsetter.
22	pub const FLOATING_POINT_TOLERANCE: f64 = 1e-12;
23	
24	// ---------------------------------------------------------------------------
25	// Rounding
26	// ---------------------------------------------------------------------------
27	
28	/// `std::llround` semantics: round half away from zero.
29	///
30	/// Rust's `f64::round` already rounds half away from zero, which is exactly
31	/// what `llround` does, so the two agree on every finite input.
32	#[inline]
33	pub fn round_i64(v: f64) -> i64 {
34	    v.round() as i64
35	}
36	
37	#[inline]
38	pub fn sqr(v: f64) -> f64 {
39	    v * v
40	}
41	
