43	// Point64 / Path64 / Paths64
44	// ---------------------------------------------------------------------------
45	
46	#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default, PartialOrd, Ord)]
47	pub struct Point64 {
48	    pub x: i64,
49	    pub y: i64,
50	}
51	
52	impl Point64 {
53	    #[inline]
54	    pub const fn new(x: i64, y: i64) -> Self {
55	        Point64 { x, y }
56	    }
57	
58	    /// Mirrors `Point64(const PointD&)`, which rounds each ordinate.
59	    #[inline]
60	    pub fn from_d(p: PointD) -> Self {
61	        Point64 {
62	            x: round_i64(p.x),
63	            y: round_i64(p.y),
64	        }
65	    }
66	
67	    #[inline]
68	    pub fn to_d(self) -> PointD {
69	        PointD {
70	            x: self.x as f64,
71	            y: self.y as f64,
72	        }
73	    }
74	}
75	
76	impl Add for Point64 {
77	    type Output = Point64;
78	    #[inline]
79	    fn add(self, o: Point64) -> Point64 {
80	        Point64::new(self.x + o.x, self.y + o.y)
81	    }
82	}
83	
84	impl Sub for Point64 {
85	    type Output = Point64;
86	    #[inline]
87	    fn sub(self, o: Point64) -> Point64 {
88	        Point64::new(self.x - o.x, self.y - o.y)
89	    }
90	}
91	
92	impl Neg for Point64 {
93	    type Output = Point64;
94	    #[inline]
95	    fn neg(self) -> Point64 {
96	        Point64::new(-self.x, -self.y)
97	    }
98	}
