100	/// A single contour.  `Vec<Point64>` mirrors `std::vector<Point64>`.
101	pub type Path64 = Vec<Point64>;
102	/// A list of contours.
103	pub type Paths64 = Vec<Path64>;
104	
105	// ---------------------------------------------------------------------------
106	// PointD
107	// ---------------------------------------------------------------------------
108	
109	#[derive(Clone, Copy, PartialEq, Debug, Default)]
110	pub struct PointD {
111	    pub x: f64,
112	    pub y: f64,
113	}
114	
115	impl PointD {
116	    #[inline]
117	    pub const fn new(x: f64, y: f64) -> Self {
118	        PointD { x, y }
119	    }
120	
121	    #[inline]
122	    pub fn from_64(p: Point64) -> Self {
123	        p.to_d()
124	    }
125	
126	    /// Length of the vector from the origin.
127	    #[inline]
128	    pub fn length(self) -> f64 {
129	        (self.x * self.x + self.y * self.y).sqrt()
130	    }
131	
132	    /// Returns the unit vector, or `(0, 0)` for a degenerate input.
133	    #[inline]
134	    pub fn normalized(self) -> PointD {
135	        let len = self.length();
136	        if len == 0.0 {
137	            PointD::new(0.0, 0.0)
138	        } else {
139	            PointD::new(self.x / len, self.y / len)
140	        }
141	    }
142	
143	    #[inline]
144	    pub fn negated(self) -> PointD {
145	        PointD::new(-self.x, -self.y)
146	    }
147	}
148	
149	impl Add for PointD {
150	    type Output = PointD;
151	    #[inline]
152	    fn add(self, o: PointD) -> PointD {
153	        PointD::new(self.x + o.x, self.y + o.y)
154	    }
155	}
156	
157	impl Sub for PointD {
158	    type Output = PointD;
159	    #[inline]
160	    fn sub(self, o: PointD) -> PointD {
161	        PointD::new(self.x - o.x, self.y - o.y)
162	    }
163	}
164	
165	impl Mul<f64> for PointD {
166	    type Output = PointD;
167	    #[inline]
168	    fn mul(self, s: f64) -> PointD {
169	        PointD::new(self.x * s, self.y * s)
170	    }
171	}
172	
173	pub type PathD = Vec<PointD>;
174	pub type PathsD = Vec<PathD>;
175	
176	/// `TranslatePoint(pt, dx, dy)`.
177	#[inline]
178	pub fn translate_point(pt: PointD, dx: f64, dy: f64) -> PointD {
179	    PointD::new(pt.x + dx, pt.y + dy)
180	}
181	
182	/// Reflects `pt` through `pivot` (`ReflectPoint`).
183	#[inline]
184	pub fn reflect_point(pt: PointD, pivot: PointD) -> PointD {
185	    PointD::new(pivot.x + (pivot.x - pt.x), pivot.y + (pivot.y - pt.y))
186	}
