245	impl Rect64 {
246	    #[inline]
247	    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
248	        Rect64 {
249	            left,
250	            top,
251	            right,
252	            bottom,
253	        }
254	    }
