432	/// Even-odd point-in-polygon test with exact `IsOn` detection, matching
433	/// `PointInPolygon`.
434	pub fn point_in_polygon(pt: Point64, polygon: &[Point64]) -> PointInPolygonResult {
435	    if polygon.len() < 3 {
436	        return PointInPolygonResult::IsOutside;
437	    }
438	    let n = polygon.len();
439	    let mut inside = false;
440	    let mut j = n - 1;
441	    for i in 0..n {
442	        let pi = polygon[i];
443	        let pj = polygon[j];
444	        if point_on_segment(pt, pj, pi) {
445	            return PointInPolygonResult::IsOn;
446	        }
447	        // Half-open crossing rule keeps vertices from being counted twice.
448	        if (pi.y > pt.y) != (pj.y > pt.y) {
449	            // Side of the edge that `pt` falls on, computed exactly.
450	            let d = cross_product_exact(pi, pj, pt);
451	            let upward = pj.y > pi.y;
452	            if (d > 0) == upward {
453	                inside = !inside;
454	            }
455	        }
456	        j = i;
457	    }
458	    if inside {
459	        PointInPolygonResult::IsInside
460	    } else {
461	        PointInPolygonResult::IsOutside
462	    }
463	}
