465	/// Winding number of `pt` with respect to the closed contour `polygon`.
466	///
467	/// Counter-clockwise (positive area) contours yield positive winding numbers
468	/// for interior points.  `pt` must not lie on the contour.
469	pub fn winding_number(pt: Point64, polygon: &[Point64]) -> i32 {
470	    let n = polygon.len();
471	    if n < 3 {
472	        return 0;
473	    }
474	    let mut wind = 0i32;
475	    let mut prev = polygon[n - 1];
476	    for &cur in polygon {
477	        if prev.y <= pt.y {
478	            if cur.y > pt.y && cross_product_exact(prev, cur, pt) > 0 {
479	                wind += 1;
480	            }
481	        } else if cur.y <= pt.y && cross_product_exact(prev, cur, pt) < 0 {
482	            wind -= 1;
483	        }
484	        prev = cur;
485	    }
486	    wind
487	}
488	
489	/// Winding number of a floating point probe against an integer contour.
490	pub fn winding_number_d(pt: PointD, polygon: &[Point64]) -> i32 {
491	    let n = polygon.len();
492	    if n < 3 {
493	        return 0;
494	    }
495	    let mut wind = 0i32;
496	    let mut prev = polygon[n - 1].to_d();
497	    for p in polygon {
498	        let cur = p.to_d();
499	        if prev.y <= pt.y {
500	            if cur.y > pt.y && cross_product_d(cur - prev, pt - prev) < 0.0 {
501	                wind += 1;
502	            }
503	        } else if cur.y <= pt.y && cross_product_d(cur - prev, pt - prev) > 0.0 {
504	            wind -= 1;
505	        }
506	        prev = cur;
507	    }
508	    wind
509	}
