515	/// Unit normal of the edge `pt1`..`pt2`, i.e. `(dy, -dx)` normalised.
516	///
517	/// For a positively oriented (counter-clockwise) contour this points away
518	/// from the interior, which is why a positive delta inflates.
519	pub fn get_unit_normal(pt1: Point64, pt2: Point64) -> PointD {
520	    let mut dx = (pt2.x - pt1.x) as f64;
521	    let mut dy = (pt2.y - pt1.y) as f64;
522	    if dx == 0.0 && dy == 0.0 {
523	        return PointD::new(0.0, 0.0);
524	    }
525	    let inv_len = 1.0 / (dx * dx + dy * dy).sqrt();
526	    dx *= inv_len;
527	    dy *= inv_len;
528	    PointD::new(dy, -dx)
529	}
