550	/// Removes consecutive duplicate vertices (and, for closed paths, a trailing
551	/// vertex equal to the first).
552	pub fn strip_duplicates(path: &[Point64], is_closed_path: bool) -> Path64 {
553	    let mut out: Path64 = Vec::with_capacity(path.len());
554	    for &pt in path {
555	        if out.last().map_or(true, |&last| last != pt) {
556	            out.push(pt);
557	        }
558	    }
559	    if is_closed_path {
560	        while out.len() > 1 && out[out.len() - 1] == out[0] {
561	            out.pop();
562	        }
563	    }
564	    out
565	}
